"""Pinned local @discord/embedded-app-sdk v2.5.0 browser bundle."""
import base64
import zlib
from aiohttp import web

SDK_VERSION = "2.5.0-1"
_SDK_ZLIB_B64 = (
    ""
)

def get_sdk_js():
    return zlib.decompress(base64.b64decode(_SDK_ZLIB_B64))


async def serve_discord_sdk(request):
    return web.Response(
        body=get_sdk_js(), content_type="application/javascript",
        headers={"Cache-Control": "public, max-age=31536000, immutable"},
    )
